// #acbc41 (6a993d6c479a31c9ebacbc41) — домен 4 «הובלת השיחה לצעד הבא»: ранний конец звонка → «אין מספיק מידע להערכה» с причиной
// окончания; отказ клиента не засчитывается кандидату; «הפעולה שהמועמד הציע», «הפער מהצעד שהוגדר», «הצעד שהוגדר בסימולציה».
// По ГОТОВЫМ отчётам (новых звонков нет): QA-bf7c47-2110 (39 с, кандидат завершил до закрытия) и QA-4b397a-DISC-2110
// (116 с, customer_refused). Кейсы REP-006, REP-007. Только чтение → @prod-safe.
import * as path from 'path';
import { Locator } from '@playwright/test';
import { test, expect } from '@playwright/test';
import { openReport } from './support';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#acbc41 · #6a993d6c479a31c9ebacbc41';
const EARLY_END_CANDIDATE = process.env.QA_EARLY_END_CANDIDATE || 'QA-bf7c47-2110';
const REFUSAL_CANDIDATE = process.env.QA_DISCOUNT_CANDIDATE || 'QA-4b397a-DISC-2110';
const DEFINED_STEP = 'פגישת ייעוץ';

/** Значение строки «dt → dd» в блоке фактов домена. */
const fact = (domain: Locator, term: string) =>
  domain.locator('dl > div').filter({ has: domain.page().locator('dt', { hasText: term }) }).locator('dd');

test.describe(`Отчёт — домен «הובלת השיחה לצעד הבא» (${HASH})`, () => {
  test(`${EARLY_END_CANDIDATE}: звонок закончен до закрытия — «אין מספיק מידע להערכה», причина «(המועמד סיים את השיחה)», шаг «${DEFINED_STEP}» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await openReport(page, EARLY_END_CANDIDATE);
    const domain = page.locator('[data-testid="report-domain"][data-domain="next_step"]');
    await expect(domain).toHaveCount(1);
    await expect(domain.getByRole('heading', { level: 3 })).toContainText('הובלת השיחה לצעד הבא');

    // Источник: AC «שיחה שהסתיימה מוקדם — אין מספיק מידע» + причина окончания (реджект 14.10 по AC5/דרישה 5).
    const state = domain.locator(':scope > header [data-testid="domain-state"]');
    await expect(state).toHaveAttribute('data-state', 'insufficient_information');
    await expect(state).toHaveText('אין מספיק מידע להערכה');
    await expect(domain.getByTestId('domain-explanation')).toContainText('השיחה הסתיימה לפני שהגיעה לשלב הסגירה (המועמד סיים את השיחה)');
    await expect(fact(domain, 'סיבת סיום השיחה')).toHaveText('המועמד סיים את השיחה');
    await expect(fact(domain, 'הצעד שהוגדר בסימולציה')).toHaveText(DEFINED_STEP);

    // Все 6 точек — тоже «אין מספיק מידע», а не «לא הודגם».
    const points = domain.getByTestId('checkpoint');
    await expect(points).toHaveCount(6);
    for (const s of await points.getByTestId('checkpoint-state').all()) await expect(s).toHaveAttribute('data-state', 'insufficient_information');
  });

  test(`${REFUSAL_CANDIDATE}: отказ клиента не засчитан кандидату; «הפעולה שהמועמד הציע», «הפער מהצעד שהוגדר», «הצעד שהוגדר בסימולציה» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await openReport(page, REFUSAL_CANDIDATE);
    const domain = page.locator('[data-testid="report-domain"][data-domain="next_step"]');
    await expect(domain).toHaveCount(1);

    // Источник: AC — шаг из симуляции, предложенное кандидатом действие и разрыв с шагом показываются.
    await expect(fact(domain, 'הצעד שהוגדר בסימולציה')).toHaveText(DEFINED_STEP);
    await expect(fact(domain, 'הפעולה שהמועמד הציע')).not.toBeEmpty();
    await expect(fact(domain, 'הפער מהצעד שהוגדר')).not.toBeEmpty();

    // Источник: AC — отказ клиента (часть сценария) не считается провалом кандидата.
    await expect(domain.getByText('הסירוב הוא חלק מהתרחיש, והוא אינו נחשב כישלון של המועמד')).toBeVisible();
    // Звонок дошёл до закрытия → оценка есть, причины «раннего конца» нет.
    const state = domain.locator(':scope > header [data-testid="domain-state"]');
    await expect(state).not.toHaveAttribute('data-state', 'insufficient_information');
    await expect(domain.locator('dt', { hasText: 'סיבת סיום השיחה' })).toHaveCount(0);
  });
});
